function drawMini(){if(!mansions.length)return;const mini=$('mini-map'),r=mini.getBoundingClientRect(),mc=mini.getContext('2d');mini.width=Math.round(r.width*dpr);mini.height=Math.round(r.height*dpr);mc.setTransform(dpr,0,0,dpr,0,0);const m=mansions[selected],points=m.members.map(s=>({id:s.id,x:-deltaAngle(s.ra,m.center.ra)*Math.cos(m.center.dec),y:-s.dec}));const xs=points.map(p=>p.x),ys=points.map(p=>p.y),minX=Math.min(...xs),minY=Math.min(...ys),maxX=Math.max(...xs),maxY=Math.max(...ys),scale=Math.min((r.width-50)/Math.max(.03,maxX-minX),(r.height-30)/Math.max(.03,maxY-minY));const pos=new Map(points.map(p=>[p.id,{x:r.width/2+(p.x-(minX+maxX)/2)*scale,y:r.height/2+(p.y-(minY+maxY)/2)*scale}]));mc.strokeStyle='#6996bb74';mc.lineWidth=.8;for(const line of m.lines){mc.beginPath();line.forEach((id,i)=>{const p=pos.get(id);if(i===0)mc.moveTo(p.x,p.y);else mc.lineTo(p.x,p.y);});mc.stroke();}for(const [id,p]of pos){const b=byId.get(id);const radius=clamp(3-b.mag*.25,1,3);const g=mc.createRadialGradient(p.x,p.y,0,p.x,p.y,9);g.addColorStop(0,'#f3d46c66');g.addColorStop(1,'#f3d46c00');mc.fillStyle=g;mc.fillRect(p.x-9,p.y-9,18,18);mc.fillStyle='#fff0a6';mc.beginPath();mc.arc(p.x,p.y,radius,0,TAU);mc.fill();}}
function linePath(samples,color,width=1,dashed=false){ctx.beginPath();let previous=null;for(const s of samples){const p=project(s.ra,s.dec);if(!p||p.x<-W||p.x>W*2||p.y<-H||p.y>H*2){previous=null;continue;}if(previous&&Math.abs(p.x-previous.x)<W*.55)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);previous=p;}ctx.strokeStyle=color;ctx.lineWidth=width;if(dashed)ctx.setLineDash([3,6]);ctx.stroke();if(dashed)ctx.setLineDash([]);}
