const glow=document.createElement('canvas');glow.width=32;glow.height=32;const gc=glow.getContext('2d'),gg=gc.createRadialGradient(16,16,0,16,16,16);gg.addColorStop(0,'#fff4b4');gg.addColorStop(.12,'#f5d35baa');gg.addColorStop(.4,'#e5c24b26');gg.addColorStop(1,'#e5c24b00');gc.fillStyle=gg;gc.fillRect(0,0,32,32);
