const modal=$('modal');function showModal(html){$('modal-content').innerHTML=html;modal.showModal();}document.querySelector('.modal-close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
$('help').onclick=()=>showModal(`<p class="eyebrow">A FIELD GUIDE TO THE SKY</p><h2>让视线，自由漫游。</h2><ul><li>鼠标拖动 / 单指滑动：天球环顾或投影平移。</li><li>滚轮 / 双指捏合 / <kbd>+</kbd> <kbd>−</kbd>：缩放。</li><li>点选星宿节点、宿名或底部文字：选择并平滑聚焦。</li><li><kbd>↑</kbd> <kbd>↓</kbd> <kbd>←</kbd> <kbd>→</kbd>：移动视角；<kbd>R</kbd>：重置。</li><li><kbd>1</kbd>–<kbd>4</kbd>：切换四象；<kbd>V</kbd>：切换投影。</li><li><kbd>[</kbd> <kbd>]</kbd>：上一宿 / 下一宿；<kbd>F</kbd>：聚焦已选星宿。</li><li><kbd>Tab</kbd>：切换界面控件；<kbd>Enter</kbd> / 空格：确认。</li></ul><p>天球以观者在球心的方式呈现。全天视角采用等距柱状投影，越接近两极形变越大。坐标固定于 J2000.0，不模拟当前地点的可见天空。</p><p>手势：首次进入网页时允许摄像头，之后无需在每次操作时重开。张掌移动带动星空，把想看的星宿移近中央准星；握拳稍作停留点亮星宿，再张掌让粒子汇聚成形。成形后展示约 4 秒，随后自动返回星空。成形期间移动手掌或鼠标，可平滑移动彩塑，并在主体粒子上产生扩散涟漪；停下后粒子平滑归位。卷云与凝像过程约 4.8 秒，随后展示约 4 秒，再散回星空。请使用单手；收起摄像头面板不影响手势，关闭摄像头按钮可随时停用。备选：鼠标或方向键环顾，W / Shift + 拖动推动星尘，M / 化形按钮触发，Esc 平滑返回。视频仅在本机处理，不上传、不录制。原图仅支持近似 2.5D，不是实测三维重建。</p>`);
$('sources').onclick=()=>showModal(`<p class="eyebrow">PROVENANCE & PRECISION</p><h2>每一颗星，都有来处。</h2><p>恒星：<a href="https://github.com/ofrohn/d3-celestial/tree/6d5e96655e0f1fe70b1eb7cf9be0eed5290e1458/data" target="_blank" rel="noreferrer">Olaf Frohn · d3-celestial</a>，HIP 标识，J2000 赤经 / 赤纬（度）、视星等。基础表为 6 等以内的 5,044 颗恒星，另补齐五颗星官成员。完整来源见本地数据清单。</p><p>星官连线：<a href="https://github.com/Stellarium/stellarium-skycultures/tree/106475b3b67488108cd5a346a737f3df42b3c7ad/chinese" target="_blank" rel="noreferrer">Stellarium · Chinese sky culture</a>。贡献者 Karrie Berglund、Sun Shuwei 及 Stellarium 团队。连线与文字声明为 CC BY-SA；本项目提取的 28 宿连线数据保留该许可。其图式综合近现代中国星表与传统资料，不视为唯一历史定本。</p><p>界面中的成员数量仅指主体星官，星宿区域内的其他附属星官未计入。详情坐标是成员球面平均中心，“最亮成员”不等同于传统距星。恒星位置不随装饰粒子、时间动画改变；此版不做岁差、自行或地平坐标转换。</p><p>化形光流为程序独立生成的视觉层，不代表真实银河亮度或星云分布。彩塑点云来自用户提供且确认使用权限的四张二十八宿拼图，摄影原图水印为乐观人文 / LeGuan Culture。保留主体轮廓和原色，以明暗及轮廓内距推断近似深度。未使用参考项目的程序或神像插画。</p><p><a href="./data/provenance.json" target="_blank">数据版本清单 ↗</a>　<a href="./data/NOTICE.txt" target="_blank">许可与署名 ↗</a></p>`);
document.addEventListener('keydown',e=>{if(experience?.busy||modal.open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.metaKey||e.ctrlKey||e.altKey)return;const k=e.key.toLowerCase();const move=(mode==='sphere'?.07:.12)/Math.sqrt(mode==='sphere'?1:camera.zoom);if(['arrowleft','arrowright','arrowup','arrowdown','+','=','-','_','[',']'].includes(k))e.preventDefault();if(k==='arrowleft')target.ra=wrap(target.ra-move);if(k==='arrowright')target.ra=wrap(target.ra+move);if(k==='arrowup')target.dec=clamp(target.dec+move,-85*RAD,85*RAD);if(k==='arrowdown')target.dec=clamp(target.dec-move,-85*RAD,85*RAD);if(k==='+'||k==='=')zoom(.85);if(k==='-'||k==='_')zoom(1.18);if(k==='r')reset();if(k==='v')setMode(mode==='sphere'?'atlas':'sphere');if(k==='f')focus(selected);if(k==='[')select(selected-1);if(k===']')select(selected+1);if(/^[1-4]$/.test(k))chooseGroup(Number(k)-1);});
window.addEventListener('resize',resize);
try{const responses=await Promise.all([fetch('./data/stars.json'),fetch('./data/mansions.json'),fetch('./data/supplement.json')]);if(responses.some(r=>!r.ok))throw new Error('星表请求失败');const [base,data,supplement]=await Promise.all(responses.map(r=>r.json()));const raw=[...base,...supplement];stars=raw.map(([id,ra,dec,mag])=>Object.freeze({id,ra:wrap(ra*RAD),dec:dec*RAD,mag}));byId=new Map(stars.map(s=>[s.id,s]));mansions=data.map(m=>{const members=[...new Set(m.lines.flat())].map(id=>{const s=byId.get(id);if(!s)throw new Error(`缺少 HIP ${id}`);return s;});const center=centerOf(members),bright=members.reduce((a,b)=>a.mag<b.mag?a:b),segments=m.lines.flatMap(line=>line.slice(1).map((id,i)=>segmentSamples(byId.get(line[i]),byId.get(id))));const span=Math.max(...members.map(s=>Math.hypot(deltaAngle(s.ra,center.ra)*Math.cos(center.dec),(s.dec-center.dec))))/RAD;return {...m,members,center,bright,segments,span};});
 $('groups').replaceChildren(...groups.map((g,i)=>{const b=document.createElement('button');b.className='group';b.setAttribute('aria-label',g.name+'七宿');b.innerHTML=`<span class="group-symbol">${g.symbol}</span><span><strong>${g.name}</strong><small>${g.en}</small></span><em>›</em>`;b.onclick=()=>chooseGroup(i);return b;}));$('mansion-strip').replaceChildren(...mansions.map((m,i)=>{const b=document.createElement('button');b.className='mansion-button'+(i%7===0&&i>0?' group-divider':'');b.textContent=m.name;b.title=groups[m.group].name+' · '+m.name+'宿';b.setAttribute('aria-label',m.name+'宿');b.onclick=()=>select(i);return b;}));defaultCamera.ra=mansions[3].center.ra;defaultCamera.dec=-9*RAD;Object.assign(camera,defaultCamera);Object.assign(target,defaultCamera);resize();select(3,false);$('loading').classList.add('hidden');$('loading').setAttribute('aria-hidden','true');requestAnimationFrame(render);
 experience=initExperience({selected:()=>({id:selected,name:mansions[selected].name}),focus:id=>focus(id),blocked:()=>modal.open||pointers.size>0,notice:toast,
  nearest:()=>nearestMansion(mansions,project,viewport),mansionName:id=>mansions[id].name,reducedMotion:reduced,
  selectionPoint:()=>{const p=project(mansions[selected].center.ra,mansions[selected].center.dec);return p?{x:p.x/W,y:p.y/H}:null;},
  handScreen:p=>({x:(viewport.cx+(p.x-.5)*viewport.w)/W,y:(viewport.cy+(p.y-.5)*viewport.h)/H}),
  selectNearest:()=>{const id=nearestMansion(mansions,project,viewport);if(id===null)return null;select(id,false);showLines=true;$('toggle-lines').setAttribute('aria-pressed','true');return id;},
  stopNavigation:()=>{target.ra=camera.ra;target.dec=camera.dec;},
  pan:(dx,dy)=>{Object.assign(target,panSky(target,mode,viewport,dx,dy));},
  snapshot:()=>({mode,camera:{...camera},activeGroup}),restore:snapshot=>{if(!snapshot)return;mode=snapshot.mode;Object.assign(target,snapshot.camera);activeGroup=snapshot.activeGroup;updateButtons();}});
 window.xingye={get state(){return {mode,selected,activeGroup,showGrid,showLines,camera:{...camera},target:{...target},starCount:stars.length,mansionCount:mansions.length,dustCount:0,...experience?.diagnostics,frameMs:frameTimes.length?frameTimes.reduce((a,b)=>a+b)/frameTimes.length:0};},get stars(){return stars;},get mansions(){return mansions;},get hitPoints(){return hitPoints;}};
 const fingerprint=()=>stars.reduce((hash,s)=>(hash+Math.round(s.ra*1e7)+Math.round(s.dec*1e7))%2147483647,0);
 setInterval(()=>{document.documentElement.dataset.diagnostics=JSON.stringify({...window.xingye.state,coordinateFingerprint:fingerprint()});},900);
}catch(error){$('loading').innerHTML='<p>星图暂未展开</p><small>请检查网络后刷新页面</small><button onclick="location.reload()" style="margin-top:24px;color:#e6c65a">重新载入 ↻</button>';console.error(error);}
